// Custom Worker entry (decision 004): OpenNext's fetch handler plus the reconcile Cron Trigger.
// OpenNext builds .open-next/worker.js; wrangler bundles this file around it.
import { openD1 } from "@gitwork/db/d1";
import { runScheduledReconcile } from "@gitwork/server/sync";
// Generated by `opennextjs-cloudflare build`; absent before the first build, so @ts-ignore.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      runScheduledReconcile(openD1(env.DB), env as unknown as Record<string, string | undefined>, crypto.randomUUID()).then((run) =>
        console.log(`[reconcile] ${JSON.stringify(run)}`),
      ),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Generated by `opennextjs-cloudflare build`; absent before the first build, so @ts-ignore.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
